from torch.utils.data import DataLoader

batch_size = 25

# Custom collate function that handles corrupted images
def safe_collate(batch):
    """Filter out None items (from failed image loads) and collate the rest"""
    batch = list(filter(lambda x: x is not None, batch))
    if len(batch) == 0:
        # Return dummy batch if no valid samples
        return torch.zeros(0, 3, 256, 256), torch.zeros(0, dtype=torch.long)

    # Default collate for valid samples
    try:
        return torch.utils.data.dataloader.default_collate(batch)
    except:
        # If collate fails, try to handle gracefully
        images, labels = zip(*batch)
        return torch.stack(images), torch.tensor(labels)

# Custom dataset wrapper that catches errors and returns None for corrupted images
class SafeDatasetWrapper:
    def __init__(self, dataset):
        self.dataset = dataset
        self.length = len(dataset)

    def __len__(self):
        return self.length

    def __getitem__(self, idx):
        try:
            return self.dataset[idx]
        except Exception as e:
            # Return None for corrupted images, will be filtered in collate
            return None

